// reviewPromptScope is best-effort context about the surface to review.
// Both fields are optional: empty values shrink or omit the scope clause
// rather than failing. Branch is the short branch name ("" = detached);
// StartingSHA is the full HEAD hash captured when the review session
// started (the same SHA stored on PendingReviewMarker.StartingSHA).
type reviewPromptScope struct {
	Branch      string
	StartingSHA string
}

// composeReviewPrompt builds the prompt sent to the agent from a
// ReviewConfig plus optional per-run context and scope. The base is
// whichever of cfg.Prompt (persistent) or a skills-composed template is
// set; per-run context, when non-empty, is appended with a clear marker
// so the agent can distinguish persistent preferences from per-run
// intent. The scope clause, when scope has a StartingSHA, pins the
// review surface to changes since the session started — without it,
// agents pick their own scope (codex defaults to `origin/main...HEAD`,
// which pulls in commits inherited from other branches and is not what
// the user is reviewing this session). Empty cfg + empty runContext +
// zero scope returns "".
func composeReviewPrompt(cfg settings.ReviewConfig, runContext string, scope reviewPromptScope) string {
	var base string
	if cfg.Prompt != "" {
		base = cfg.Prompt
	} else if len(cfg.Skills) > 0 {
		var sb strings.Builder
		sb.WriteString("Please run these review skills in order:\n")
		for i, skill := range cfg.Skills {
			fmt.Fprintf(&sb, "  %d. %s\n", i+1, skill)
		}
		base = sb.String()
	}

	if runContext != "" {
		if base == "" {
			base = runContext
		} else {
			base = base + "\n\nFor this review: " + runContext
		}
	}

	clause := scopeClause(scope)
	if clause == "" {
		return base
	}
	if base == "" {
		return clause
	}
	return base + "\n\n" + clause
}

// scopeClause renders the scope hint appended to the agent prompt.
// Returns "" when scope carries no usable information (no SHA), since
// without an anchor the clause would be lying about what to review.
func scopeClause(scope reviewPromptScope) string {
	if scope.StartingSHA == "" {
		return ""
	}
	var sb strings.Builder
	sb.WriteString("Review scope: changes since this review session started")
	if scope.Branch != "" {
		fmt.Fprintf(&sb, " on branch `%s`", scope.Branch)
	}
	fmt.Fprintf(&sb, " (HEAD was `%s` at session start), including any uncommitted changes.\n", scope.StartingSHA)
	fmt.Fprintf(&sb, "Use `git diff %s..HEAD` and `git status --porcelain` to find the surface to review. ", scope.StartingSHA)
	sb.WriteString("Do not review commits older than that SHA — those came from other branches and are not the focus of this session.")
	return sb.String()
}

